<div class="{{ auth()->user()->isRole('system_administrator','mis_head')?'col-xl-8':'col-12' }}"><section class="panel"><div class="panel-header"><div><h2>Maintenance schedule</h2><p>Planned work, assignments and recorded findings.</p></div></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Date / asset</th><th>Task</th><th>Technician</th><th>Status</th><th>Inspection record / action</th></tr></thead><tbody>@forelse($schedules as $schedule)<tr><td>{{ $schedule->scheduled_for->format('M j, Y') }}<div class="small text-muted">{{ $schedule->asset->asset_tag }} · {{ $schedule->asset->name }}</div></td><td><strong>{{ $schedule->title }}</strong><div class="small text-muted">{{ $schedule->instructions }}</div></td><td>{{ $schedule->technician?->name ?? 'Unassigned' }}</td><td>{{ $schedule->status }}</td><td>@if($schedule->record)<div class="small"><strong>Findings:</strong> {{ $schedule->record->findings }}<br><strong>Actions:</strong> {{ $schedule->record->actions_performed }}<br><strong>Next:</strong> {{ $schedule->record->next_maintenance_on?->format('M j, Y') ?? 'Not set' }}</div>@elseif($schedule->status!=='Cancelled')<details><summary class="text-link">Update</summary><form method="POST" action="{{ route('maintenance.update',$schedule) }}" class="mt-2" style="min-width:240px">@csrf @method('PATCH')<label class="form-label">Status</label><select name="status" class="form-select form-select-sm mb-2" id="maintenance-{{ $schedule->id }}" required>@foreach(['Scheduled','In Progress','Completed','Cancelled'] as $v)<option @selected($schedule->status===$v)>{{ $v }}</option>@endforeach</select><div class="completion-fields d-none"><label class="form-label">Findings</label><textarea name="findings" class="form-control form-control-sm mb-2" rows="2"></textarea><label class="form-label">Actions performed</label><textarea name="actions_performed" class="form-control form-control-sm mb-2" rows="2"></textarea><label class="form-label">Next maintenance date</label><input name="next_maintenance_on" type="date" class="form-control form-control-sm mb-2"></div><button class="btn btn-sm btn-primary">Save</button></form></details>@endif</td></tr>@empty<tr><td colspan="5"><div class="empty-state">No scheduled maintenance records.</div></td></tr>@endforelse</tbody></table></div><div class="p-3">{{ $schedules->links() }}</div></section></div></div>@endsection
